tools.example:
open_project ./proj/top.xpr

# Three implementation runs from the same synthesis, different strategies
foreach s {Performance_Explore Performance_ExtraTimingOpt Congestion_SpreadLogic_high} {
  create_run impl_$s -parent_run synth_1 \
    -flow {Vivado Implementation 2024} -strategy $s -constrset constrs_1
}

launch_runs [get_runs impl_Performance_*] -jobs 12
wait_on_run -quiet [get_runs impl_Performance_*]

foreach r [get_runs impl_*] {
  puts "[get_property NAME $r]: WNS = [get_property STATS.WNS $r]"
}

open_project ./proj/top.xpr

set_property STRATEGY Flow_PerfOptimized_high [get_runs synth_1]
set_property STRATEGY Performance_Explore     [get_runs impl_1]

# Strategy sweep: one run per strategy, all launched together
set strategies {Performance_Explore Performance_ExtraTimingOpt \
                Congestion_SpreadLogic_high Area_Explore}
foreach s $strategies {
  create_run impl_$s -parent_run synth_1 -flow {Vivado Implementation 2024}
  set_property STRATEGY $s [get_runs impl_$s]
}
launch_runs [get_runs impl_*] -jobs 16
wait_on_run -quiet [get_runs impl_*]

foreach r [get_runs impl_*] {
  puts [format "%-40s WNS %6s  WHS %6s" [get_property NAME $r] \
        [get_property STATS.WNS $r] [get_property STATS.WHS $r]]
}
